//! Icon asset paths used by HeroGPUI components.
//!
//! Components reference icons through these stable asset paths. Applications
//! must register an [`gpui::AssetSource`] that can resolve them — the gallery
//! app embeds the SVGs shipped in `assets/herogpui/icons`.

/// Asset path prefix shared by all HeroGPUI icons.
pub const ICON_PREFIX: &str = "herogpui/icons";

/// Asset path of the `spinner` icon.
pub const SPINNER: &str = "herogpui/icons/spinner.svg";
